import { LayoutList, LayoutGrid, Users } from 'lucide-react'

type ViewMode = 'list' | 'grid' | 'people'

type Props = {
  value: ViewMode
  onChange: (value: ViewMode) => void
  className?: string
}

const MODES: { value: ViewMode; Icon: typeof LayoutList }[] = [
  { value: 'list', Icon: LayoutList },
  { value: 'grid', Icon: LayoutGrid },
  { value: 'people', Icon: Users },
]

export function ViewModeToggle({ value, onChange, className }: Props) {
  return (
    <div className={`inline-flex items-center border border-border rounded-lg bg-card ${className ?? ''}`}>
      {MODES.map(({ value: mode, Icon }) => (
        <button
          key={mode}
          onClick={() => onChange(mode)}
          className={`p-2 transition-colors ${
            value === mode ? 'text-primary' : 'text-muted-foreground hover:text-foreground'
          }`}
          aria-label={mode}
        >
          <Icon size={16} />
        </button>
      ))}
    </div>
  )
}
